std::string hex(std::string_view s){constexpr char d[]="0123456789abcdef";std::string r;for(unsigned char c:s){r+=d[c>>4];r+=d[c&15];}return r;}
std::string view(const Value& input){const auto& v=input.view();switch(v.kind){case Value::Kind::Undefined:return "u";case Value::Kind::String:return "s"+hex(v.text);case Value::Kind::Integer:return "i"+std::to_string(v.integer);case Value::Kind::Boolean:return v.boolean?"b1":"b0";case Value::Kind::Uuid:return "q"+v.text;case Value::Kind::Array:{std::string s="[";for(const auto& x:v.array){if(s.size()>1)s+=',';s+=view(x);}return s+"]";}case Value::Kind::Map:{std::string s="{";for(const auto& [key,x]:v.map){if(s.size()>1)s+=',';s+=hex(key)+"="+view(x);}return s+"}";}default:throw std::runtime_error("view");}}
LoginResponse::Text text(std::string s){if(s=="-")return {};return s=="."?std::string{}:fixture::unhex(s);}
Value array(){Value v;v.kind=Value::Kind::Array;return v;}
LoginResponse::Node list(int mode){if(!mode)return {};auto v=std::make_shared<Value>(array());if(mode==2)v->array.push_back(Value::object({{"name",""},{"null",Value{}},{"i",Value(std::int32_t{1})},{"bool",Value(false)}}));if(mode==3)v->array.emplace_back("wrong");if(mode==4)v->array.push_back(Value::object({{"map",Value::object({})},{"array",array()}}));return v;}
